CREATE TABLE plots (
  geom GEOSILO('EPSG:3857')
    USING COMPRESSION zstd
);
INSERT INTO plots VALUES (
  'POLYGON((0 0,10 0,10 10,0 10,0 0))'
    ::GEOMETRY
);

WITH encoded AS (
  SELECT geosilo_encode(
    'POINT(1.234 2.345)'::GEOMETRY,100
  ) AS blob
)
SELECT geosilo_decode(blob)::VARCHAR AS wkt
FROM encoded;
